<style>
.account-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,.65fr);gap:20px}.account-summary dl{display:grid;grid-template-columns:130px minmax(0,1fr);gap:10px 16px;margin:0}.account-summary dt{color:var(--muted);font-weight:700}.account-summary dd{margin:0}.password-stack{display:grid;gap:16px;max-width:620px}.password-field{position:relative;margin-top:5px}.password-field input{margin:0;padding-right:52px}.password-toggle{position:absolute;top:50%;right:5px;display:grid;width:40px;height:40px;padding:0;place-items:center;transform:translateY(-50%);border:0;border-radius:8px;background:transparent;color:inherit;cursor:pointer}.password-toggle:hover{background:rgba(15,72,94,.08)}.password-toggle:focus-visible{outline:2px solid var(--blue);outline-offset:1px}.password-toggle svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:2}.password-toggle .eye-off{display:none}.password-toggle[aria-pressed="true"] .eye-on{display:none}.password-toggle[aria-pressed="true"] .eye-off{display:block}.success{background:#f3faed;color:#285c20;border:1px solid #9acb70;padding:12px;border-radius:9px;margin-bottom:16px}@media(max-width:760px){.account-grid{grid-template-columns:1fr}.account-summary dl{grid-template-columns:1fr;gap:2px}.account-summary dd{margin-bottom:10px}}
