<script nonce="<?=htmlspecialchars(\App\Core\Security::nonce(),ENT_QUOTES,'UTF-8')?>">(()=>{document.querySelectorAll('.password-toggle').forEach(button=>{const input=document.getElementById(button.getAttribute('aria-controls'));if(!input)return;button.addEventListener('click',()=>{const show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',show?'true':'false');button.setAttribute('aria-label',(show?'Nascondi ':'Mostra ')+(input.previousElementSibling?.textContent||'password'));input.focus()})})})();</script>
